import{_ as t,o as a,c as n,ah as r}from"./chunks/framework.C-FRNfAJ.js";const m=JSON.parse('{"title":"Settings","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/administrateur/reglages.md","filePath":"src/en/guide/administrateur/reglages.md"}'),o={name:"en/guide/administrateur/reglages.md"};function s(i,e,l,d,g,h){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p><strong>Administration → Settings</strong> gathers the application&#39;s general parameters. They apply to everything Kura produces afterwards: agreements, invoices, certificates.</p><h2 id="agreements-and-legal-mentions" tabindex="-1">Agreements and legal mentions <a class="header-anchor" href="#agreements-and-legal-mentions" aria-label="Permalink to &quot;Agreements and legal mentions&quot;">​</a></h2><ul><li><strong>Counter-signature of agreements</strong>: <strong>Automatic, in the representative&#39;s name</strong> (default), or <strong>By the Pedagogical Coordinator</strong>. The same setting applies to the training agreement, the tripartite, the internship agreement and the partnership contract. In manual mode, the Coordinator counter-signs them, or a Partnerships Officer for a partnership.</li><li><strong>Representative of edPage group</strong>, in whose name automatic counter-signature is made.</li><li><strong>Registered address</strong>, <strong>RCCM</strong> and <strong>NIF</strong>: printed on documents.</li></ul><h2 id="invoices" tabindex="-1">Invoices <a class="header-anchor" href="#invoices" aria-label="Permalink to &quot;Invoices&quot;">​</a></h2><ul><li><strong>VAT mention</strong>: the exemption mention printed on each invoice (amounts are excluding tax).</li><li><strong>Payment details</strong>: Mobile Money numbers, bank details and others, printed on each invoice and shown to the learner.</li><li><strong>Placement fee</strong> and <strong>support fee</strong> (FCFA, per retained profile). <strong>As long as these fees are not set, confirming a placement is impossible.</strong> See <a href="./../entreprises/recrutement.html">Recruiting certified profiles</a>.</li></ul><h2 id="certificate-mentions" tabindex="-1">Certificate mentions <a class="header-anchor" href="#certificate-mentions" aria-label="Permalink to &quot;Certificate mentions&quot;">​</a></h2><p>The thresholds, as an average out of 20, from which a certificate carries the mention <strong>Assez bien</strong>, <strong>Bien</strong> or <strong>Très bien</strong>. Below the first threshold, the mention is &quot;Passable&quot; (from 10/20). Default values are 12, 14 and 16.</p><h2 id="profitability-zones" tabindex="-1">Profitability zones <a class="header-anchor" href="#profitability-zones" aria-label="Permalink to &quot;Profitability zones&quot;">​</a></h2><p>The <strong>Viable</strong> and <strong>Comfortable</strong> thresholds of each program category (Career Paths, Job Skills, Technologies &amp; Tools), expressed in confirmed enrolments, between 1 and 15. The Comfortable threshold must be <strong>above</strong> the Viable threshold. Below the Viable threshold, the cohort is Fragile.</p><p>A change only touches <strong>upcoming cohorts</strong>: a cohort that has started keeps its start zone, and so do remunerations.</p><h2 id="public-holidays" tabindex="-1">Public holidays <a class="header-anchor" href="#public-holidays" aria-label="Permalink to &quot;Public holidays&quot;">​</a></h2><p><strong>Administration → Public holidays</strong>: add a date and its label, or delete it. Admission deadlines are counted in <strong>working days</strong> (Monday to Friday) excluding these days. <strong>Enter movable feasts every year.</strong> Due dates already set keep their date.</p>',13)])])}const u=t(o,[["render",s]]);export{m as __pageData,u as default};
